from typing import Dict, List, Union
from urllib.parse import urlparse

from starlette.routing import Route, Router
from starlette.requests import Request
from starlette.responses import JSONResponse, Response

from ..exceptions import AuthServerExceptionCode, MCPAuthAuthServerException
from ..types import ResourceServerConfig
from ..config import ProtectedResourceMetadata
from ..utils import (
    create_resource_metadata_endpoint,
    transpile_resource_metadata,
    validate_server_config,
)
from .mcp_auth_handler import MCPAuthHandler
from .token_verifier import TokenVerifier


class ResourceServerModeConfig:
    """
    Configuration for the MCP-server-as-resource-server mode.
    """

    def __init__(
        self,
        protected_resources: Union[ResourceServerConfig, List[ResourceServerConfig]],
    ):
        self.protected_resources = protected_resources


class ResourceServerHandler(MCPAuthHandler):
    """
    Handles the authentication logic for the MCP server as resource server mode.
    """

    _token_verifiers: Dict[str, TokenVerifier]
    _resources_configs: List[ResourceServerConfig]

    def __init__(self, config: ResourceServerModeConfig):
        self._resources_configs = self._get_resources_configs(config)
        self._validate_config(self._resources_configs)

        self._token_verifiers = {}
        for resource_config in self._resources_configs:
            resource = resource_config.metadata.resource
            auth_servers = resource_config.metadata.authorization_servers or []
            self._token_verifiers[resource] = TokenVerifier(auth_servers)

    def create_metadata_route(self) -> Router:
        routes: List[Route] = []
        for resource_config in self._resources_configs:
            metadata = transpile_resource_metadata(resource_config.metadata)
            endpoint_path = create_resource_metadata_endpoint(metadata.resource)

            def endpoint(
                request: Request, _metadata: ProtectedResourceMetadata = metadata
            ) -> Response:
                if request.method == "OPTIONS":
                    response = Response(status_code=204)
                else:
                    response = JSONResponse(_metadata.model_dump(exclude_none=True))
                response.headers["Access-Control-Allow-Origin"] = "*"
                response.headers["Access-Control-Allow-Methods"] = "GET, OPTIONS"
                response.headers["Access-Control-Allow-Headers"] = "*"
                return response

            routes.append(
                Route(
                    urlparse(endpoint_path).path,
                    endpoint=endpoint,
                    methods=["GET", "OPTIONS"],
                )
            )
        return Router(routes=routes)

    def get_token_verifier(self, resource: str) -> TokenVerifier:
        verifier = self._token_verifiers.get(resource)

        if not verifier:
            raise MCPAuthAuthServerException(
                AuthServerExceptionCode.INVALID_SERVER_CONFIG,
                cause={
                    "error_description": f"No token verifier found for the specified resource: `{resource}`. Please ensure that this resource is correctly configured in the `protectedResources` array in the MCPAuth constructor."
                },
            )

        return verifier

    def _get_resources_configs(
        self, config: ResourceServerModeConfig
    ) -> List[ResourceServerConfig]:
        if isinstance(config.protected_resources, list):
            return config.protected_resources
        return [config.protected_resources]

    def _validate_config(self, resource_configs: List[ResourceServerConfig]):
        unique_resources: set[str] = set()

        for resource_config in resource_configs:
            resource = resource_config.metadata.resource
            if resource in unique_resources:
                raise MCPAuthAuthServerException(
                    AuthServerExceptionCode.INVALID_SERVER_CONFIG,
                    cause={"error_description": f"The resource metadata ('{resource}') is duplicated."},
                )
            unique_resources.add(resource)

            unique_auth_servers: set[str] = set()
            if resource_config.metadata.authorization_servers:
                for auth_server in resource_config.metadata.authorization_servers:
                    issuer = auth_server.metadata.issuer
                    if issuer in unique_auth_servers:
                        raise MCPAuthAuthServerException(
                            AuthServerExceptionCode.INVALID_SERVER_CONFIG,
                            cause={"error_description": f"The authorization server ('{issuer}') for resource '{resource}' is duplicated."},
                        )
                    unique_auth_servers.add(issuer)
                    validate_server_config(auth_server)

from typing import List, Union
from jwt import PyJWK, PyJWKClient, PyJWTError, decode
from pydantic import ValidationError
from ..types import AuthInfo, JwtPayload, VerifyAccessTokenFunction
from ..exceptions import (
    MCPAuthTokenVerificationException,
    MCPAuthTokenVerificationExceptionCode,
)


def create_verify_jwt(
    input: Union[str, PyJWKClient, PyJWK],
    algorithms: List[str] = ["RS256", "PS256", "ES256", "ES384", "ES512"],
    leeway: float = 60,
) -> VerifyAccessTokenFunction:
    """
    Creates a JWT verification function using the provided JWKS URI.

    :param input: Supports one of the following:
        - A JWKS URI (string) that points to a JSON Web Key Set.
        - An instance of `PyJWKClient` that has been initialized with the JWKS URI.
        - An instance of `PyJWK` that represents a single JWK.
    :param algorithms: A list of acceptable algorithms for verifying the JWT signature.
    :param leeway: The amount of leeway (in seconds) to allow when checking the expiration time of the JWT.
    :return: A function that can be used to verify JWTs.
    :raises MCPAuthTokenVerificationException: If the JWT verification fails.
    """

    jwks = (
        input
        if isinstance(input, PyJWKClient)
        else (
            PyJWKClient(
                input, headers={"user-agent": "@mcp-auth/python", "accept": "*/*"}
            )
            if isinstance(input, str)
            else input
        )
    )

    def verify_jwt(token: str) -> AuthInfo:
        try:
            signing_key = (
                jwks.get_signing_key_from_jwt(token)
                if isinstance(jwks, PyJWKClient)
                else jwks
            )
            decoded = decode(
                token,
                signing_key.key,
                algorithms=algorithms,
                leeway=leeway,
                options={
                    "verify_aud": False,
                    "verify_iss": False,
                },
            )
            base_model = JwtPayload(**decoded)
            scopes = base_model.scope or base_model.scopes
            return AuthInfo(
                token=token,
                issuer=base_model.iss,
                client_id=(
                    base_model.client_id
                    if base_model.client_id is not None
                    else base_model.azp
                ),
                subject=base_model.sub,
                audience=base_model.aud,
                scopes=(scopes.split(" ") if isinstance(scopes, str) else scopes) or [],
                claims=decoded,
            )
        except (PyJWTError, ValidationError) as e:
            raise MCPAuthTokenVerificationException(
                MCPAuthTokenVerificationExceptionCode.INVALID_TOKEN,
                cause=e,
            )
        except Exception as e:
            raise MCPAuthTokenVerificationException(
                MCPAuthTokenVerificationExceptionCode.TOKEN_VERIFICATION_FAILED,
                cause=e,
            )

    return verify_jwt

from enum import Enum
from pydantic import BaseModel
from typing import Any, Optional, List, Dict, Union
from .types import Record

ExceptionCause = Optional[Union[Record, Exception, BaseModel]]


class MCPAuthException(Exception):
    """
    Base class for all mcp-auth exceptions.
    This class provides a standardized way to handle exceptions related to MCP authentication and authorization.
    """

    def __init__(
        self, code: Union[str, Enum], message: str, cause: ExceptionCause = None
    ):
        """
        :param code: A unique exception code in snake_case format that identifies the type of exception.
        :param message: A human-readable description of the exception.
        """

        self.code = code
        self.message = message
        self.cause = cause
        super().__init__(message)

    def to_json(self, show_cause: bool = False) -> Record:
        """
        Converts the exception to a HTTP response friendly JSON format.

        :param show_cause: Whether to include the cause of the exception in the JSON response. Defaults to `false`.
        """
        data: Record = {
            "error": self.code.value if isinstance(self.code, Enum) else self.code,
            "error_description": self.message,
            "cause": (
                (
                    self.cause.model_dump(exclude_none=True)
                    if isinstance(self.cause, BaseModel)
                    else str(self.cause)
                )
                if show_cause and hasattr(self, "cause")
                else None
            ),
        }
        return {k: v for k, v in data.items() if v is not None}


class MCPAuthConfigException(MCPAuthException):
    """
    Exception thrown when there is a configuration issue with mcp-auth.
    """


class AuthServerExceptionCode(str, Enum):
    INVALID_SERVER_METADATA = "invalid_server_metadata"
    INVALID_SERVER_CONFIG = "invalid_server_config"
    MISSING_JWKS_URI = "missing_jwks_uri"


auth_server_exception_description: Dict[AuthServerExceptionCode, str] = {
    AuthServerExceptionCode.INVALID_SERVER_METADATA: "The server metadata is invalid or malformed.",
    AuthServerExceptionCode.INVALID_SERVER_CONFIG: "The server configuration does not match the MCP specification.",
    AuthServerExceptionCode.MISSING_JWKS_URI: "The server metadata does not contain a JWKS URI, which is required for JWT verification.",
}


class MCPAuthAuthServerException(MCPAuthException):
    """
    Exception thrown when there is an issue with the remote authorization server.
    """

    def __init__(self, code: AuthServerExceptionCode, cause: ExceptionCause = None):
        super().__init__(
            code.value,
            auth_server_exception_description.get(
                code, "An exception occurred with the authorization server."
            ),
        )
        self.code = code
        self.cause = cause


class BearerAuthExceptionCode(str, Enum):
    MISSING_AUTH_HEADER = "missing_auth_header"
    INVALID_AUTH_HEADER_FORMAT = "invalid_auth_header_format"
    MISSING_BEARER_TOKEN = "missing_bearer_token"
    INVALID_ISSUER = "invalid_issuer"
    INVALID_AUDIENCE = "invalid_audience"
    MISSING_REQUIRED_SCOPES = "missing_required_scopes"
    INVALID_TOKEN = "invalid_token"


bearer_auth_exception_description: Dict[BearerAuthExceptionCode, str] = {
    BearerAuthExceptionCode.MISSING_AUTH_HEADER: "Missing `Authorization` header. Please provide a valid bearer token.",
    BearerAuthExceptionCode.INVALID_AUTH_HEADER_FORMAT: 'Invalid `Authorization` header format. Expected "Bearer <token>".',
    BearerAuthExceptionCode.MISSING_BEARER_TOKEN: "Missing bearer token in `Authorization` header. Please provide a valid token.",
    BearerAuthExceptionCode.INVALID_ISSUER: "The token issuer does not match the expected issuer.",
    BearerAuthExceptionCode.INVALID_AUDIENCE: "The token audience does not match the expected audience.",
    BearerAuthExceptionCode.MISSING_REQUIRED_SCOPES: "The token does not contain the necessary scopes for this request.",
    BearerAuthExceptionCode.INVALID_TOKEN: "The provided token is not valid or has expired.",
}


class MCPAuthBearerAuthExceptionDetails(BaseModel):
    cause: Any = None
    uri: Optional[str] = None
    missing_scopes: Optional[List[str]] = None
    expected: Any = None
    actual: Any = None


class MCPAuthBearerAuthException(MCPAuthException):
    """
    Exception thrown when there is an issue when authenticating with Bearer tokens.
    """

    def __init__(
        self,
        code: BearerAuthExceptionCode,
        cause: Optional[MCPAuthBearerAuthExceptionDetails] = None,
    ):
        super().__init__(
            code.value,
            bearer_auth_exception_description.get(
                code, "An exception occurred with the Bearer auth."
            ),
        )
        self.code = code
        self.cause = cause

    def to_json(self, show_cause: bool = False) -> Dict[str, Optional[str]]:
        # Matches the OAuth 2.0 exception response format at best effort
        data = super().to_json(show_cause)
        if self.cause:
            data.update(
                {
                    "error_uri": self.cause.uri,
                    "missing_scopes": self.cause.missing_scopes,
                }
            )
        return {k: v for k, v in data.items() if v is not None}


class MCPAuthTokenVerificationExceptionCode(str, Enum):
    INVALID_TOKEN = "invalid_token"
    TOKEN_VERIFICATION_FAILED = "token_verification_failed"


token_verification_exception_description: Dict[
